type Course = {
  id: number;
  title: string;
};

@Injectable()
export class CoursesService {
  private readonly courses:
    Course[] = [
      {
        id: 1,
        title: 'TypeScript',
      },
      {
        id: 2,
        title: 'NestJS',
      },
    ];

  getCourses(): Course[] {
    return this.courses;
  }

  createCourse(
    title: string,
  ): Course {
    const course: Course = {
      id:
        this.courses.length +
        1,
      title,
    };

    this.courses.push(
      course,
    );

    return course;
  }
}

