package com.elab.app;

import jakarta.validation.ConstraintViolation;
import jakarta.validation.Validator;
import java.lang.reflect.Field;
import java.util.Set;
import java.util.TreeSet;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ElabProbeValidationController {

    private final Validator validator;

    public ElabProbeValidationController(Validator validator) {
        this.validator = validator;
    }

    @GetMapping("/elab-probe/validate")
    public String validate(@RequestParam(defaultValue = "") String name, @RequestParam int score) throws Exception {
        StudentRequest request = StudentRequest.class.getDeclaredConstructor().newInstance();
        Field nameField = StudentRequest.class.getDeclaredField("name");
        nameField.setAccessible(true);
        nameField.set(request, name);
        Field scoreField = StudentRequest.class.getDeclaredField("score");
        scoreField.setAccessible(true);
        scoreField.setInt(request, score);
        Set<String> invalid = new TreeSet<>();
        for (ConstraintViolation<StudentRequest> violation : validator.validate(request)) {
            invalid.add(violation.getPropertyPath().toString());
        }
        return invalid.isEmpty() ? "VALID" : String.join(",", invalid);
    }
}

